static uint32_t fm1_clk320_loop_ticks(void)
{
    uint32_t best = ~0u, t, k;
    fclk_adds(4);                               /* the loop into the cache */
    for (k = 0; k < 3u; k++) {
        t = fm1_ticks();
        fclk_adds(4000);
        t = fm1_ticks() - t;
        if (t < best)
            best = t;
    }
    return best;
}

