/* the cell at x in the row at y: s its letter (number), in state st; c a tile's fill and a staged one's outline and
 * letter, ink a tile's letter, kc a kept one's letter, dc an empty one's dot, g the ground; u: underlined */
static void perf_cell(int32_t x, int32_t y, const char *s, uint32_t st, uint16_t c, uint16_t ink, uint16_t kc,
                      uint16_t dc, uint16_t g, int u)
{
    int32_t ty = y + (PR_H - PR_TH) / 2, b[4];
    uint16_t lc = st == PC_ON ? ink : st == PC_NEXT ? c : kc, on = st == PC_ON ? c : g;
    if (st == PC_EMPTY) {
        cv_rect(x + PR_W / 2 - 1, y + PR_H / 2 - 1, 2, 2, dc);
        return;
    }
    if (st == PC_ON)
        cv_rrect(x, ty, PR_W, PR_TH, 2, c, g);
    else if (st == PC_NEXT)
        cv_frame(x, ty, PR_W, PR_TH, c);
    GFX_HOOK_ALIGN(x, ty, x + PR_W, ty + PR_TH, AL_HV, "perform cell letter centred");
    cv_text_in(x, ty + CAP_IN(S, PR_TH), PR_W, &AF_S, s, lc, on);
    if (u) {                                          /* (under the letter's ink, 2 px below its foot) */
        text_ink(&AF_S, s, b);
        cv_rect(x + ink_in(&AF_S, s, PR_W) + b[0], ty + PR_TH - 2, b[2] - b[0], 1, lc);
    }
}

static void pd_setup(pd_t *b, uint32_t w, uint32_t dcw)
{
    uint32_t x;
    b->w = w;
    b->old = 0;
    switch (w) {
    case 0:                                                  /* SAW */
        x = 32768u + ((dcw * 32767u) >> 16);
        b->k0 = pd_slope(32768u, x);
        b->k1 = pd_slope(32767u, 65535u - x);
        break;
    case 1:                                                  /* SQUARE */
        x = 32768u - ((dcw * 31120u) >> 16);
        b->k0 = pd_slope(32768u, x);
        b->k1 = pd_slope(32767u, x);
        break;
    case 2:                                                  /* PULSE */
        x = 65535u - ((dcw * 63487u) >> 16);
        b->k0 = pd_slope(65535u, x);
        break;
    case 3:                                                  /* DOUBLE SINE */
        x = 65535u - ((dcw * 49151u) >> 16);
        b->k0 = pd_slope(65535u, x);
        b->k1 = pd_slope(65535u, 65535u - x);
        break;
    case 4:                                                  /* SAW-PULSE */
        x = 65535u - ((dcw * 32767u) >> 16);
        b->peak = (x * (32768u + ((dcw * 29491u) >> 16))) >> 16;
        if (!b->peak)
            b->peak = 1;
        b->k0 = pd_slope(32768u, b->peak);
        b->k1 = pd_slope(32767u, x - b->peak);
        break;
    default:                                                 /* RESONANCE */
        x = 0;
        b->rez = (dcw * 44000u) >> 16;
        break;
    }
    b->x = x;
}

/* one oscillator over the block: mix[i] += its sample at level g, its steps into cr; one loop per
 * wave, so the wave is not looked at per sample. wx (osc 1 of a SYNC set: saw or pulse): where it
 * starts a cycle, how far before sample i (Q15), else -1 */
static void trio_pass(uint32_t w, uint32_t *php, uint32_t inc, int32_t g, const trio_pw_t *q, int32_t *nz,
                      int32_t *nst, int32_t *mix, int32_t *cr, int16_t *wx, uint32_t n)
{
    uint32_t ph = *php, o, i, pw = q->pw;
    int32_t pdc = q->pdc, z = *nz;
    switch (w) {
    case TW_TRI:
        for (i = 0; i < n; i++) {
            ph += inc;
            mix[i] += (osc_tri(ph) * g) >> 15;
        }
        break;
    case TW_SAW:
        for (i = 0; i < n; i++) {
            o = ph;
            ph += inc;
            if (ph < o) {
                int32_t x = trio_frac(ph, inc);
                trio_blep(-65536, x, g, cr + i);
                if (wx)
                    wx[i] = (int16_t)x;
            }
            mix[i] += (((int32_t)(ph >> 16) - 32768) * g) >> 15;
        }
        break;
    case TW_PLS:
        for (i = 0; i < n; i++) {
            o = ph;
            ph += inc;
            if (ph < o) {
                int32_t x = trio_frac(ph, inc);
                trio_blep(65535, x, g, cr + i);
                if (wx)
                    wx[i] = (int16_t)x;
            }
            if (ph - pw < o - pw)                       /* crossed pw */
                trio_blep(-65535, trio_frac(ph - pw, inc), g, cr + i);
            mix[i] += (((ph < pw ? 32767 : -32768) - pdc) * g) >> 15;
        }
        break;
    case TW_NOI:
        for (i = 0; i < n; i++) {
            o = ph;
            ph += inc;
            if ((o ^ ph) & 0x08000000u)
                z = (int32_t)(noise32(nst) >> 16) - 32768;
            mix[i] += (z * g) >> 15;
        }
        break;
    case TW_ST:
        for (i = 0; i < n; i++) {
            ph += inc;
            mix[i] += (trio_st(ph) * g) >> 15;
        }
        break;
    case TW_PS:
        for (i = 0; i < n; i++) {
            ph += inc;
            mix[i] += (trio_ps(ph, q) * g) >> 15;
        }
        break;
    default:                                            /* silent: the phase still runs (RING) */
        ph += inc * n;
        break;
    }
    *php = ph;
    *nz = z;
}

static void grain_render(track_t *t, voice_t *v, int32_t *out, uint32_t n, const vmod_t *m)
{
    gr_part_t *P = (gr_part_t *)eng_part(t);   /* (Skiff: the part's shared area, engines.c) */
    const int16_t *p = t->p;
    uint32_t vi = (uint32_t)(v - t->v) % NVOICE, i, mine = 0, nact = 0, iv;
    int32_t zl = v->s[0], acc[CTL], lp, y = v->s[2];
    if (grain_off(t))
        return;
    if (n > CTL)
        n = CTL;
    if (zl == GR_SINE) {                            /* no data: a plain sine at the note's pitch + PTCH, TONE */
        lp = 4000 + ((clamp((p[P_E7] << 8) + m->cutoff, 0, 127 << 8) * 28767) >> 15);
        smp_sine(out, n, m, p[P_E4] * 16, lp, &v->ph[0], &v->s[2]);
        return;
    }
    if (zl < 0 || zl >= P->nz || P->src != (uint32_t)p[P_E0] % SMP_NALL + 1u) {
        if (zl < 0)
            v->active = 0;                          /* a user slot key with no zone: silent */
        return;
    }
    for (i = 0; i < n; i++)
        acc[i] = 0;
    for (i = 0; i < GR_POLY; i++)
        nact += t->v[i].active;
    for (i = 0; i < GR_NG; i++)
        if (P->g[i].owner == vi + 1u)
            mine += gr_run(P, &P->g[i], acc, n);
    /* the next grain: DENS a second, 1..98 /s (SPRD jitters the interval) */
    iv = (44100u * pow2_q16(-p[P_E3] * 10)) >> 16;
    v->s[1] -= (int32_t)n;
    if (v->s[1] <= 0) {
        uint32_t r = gr_rnd(P);
        int32_t j = (((int32_t)(r & 0xFFFFu) - 32768) * p[P_E5]) / 254;   /* +-SPRD / 2, Q15 */
        v->s[1] += (int32_t)iv + mulq15((int32_t)iv, j);
        if (v->s[1] < 0)
            v->s[1] = 0;
        if (mine < (nact > 1u ? (GR_NG / nact > 2u ? GR_NG / nact : 2u) : GR_NG))
            gr_spawn(P, t, vi, (uint32_t)zl, iv, m);
    }
    lp = 4000 + ((clamp((p[P_E7] << 8) + m->cutoff, 0, 127 << 8) * 28767) >> 15);
    for (i = 0; i < n; i++) {
        y += mulq15(clamp(acc[i], -65535, 65535) - y, lp);
        out[i] += voice_amp(y, m, i) << 1;
    }
    v->s[2] = y;
}

/* tau (us) -> per-block decay, Q16: e^(-CTL / (tau fs)), to the fourth order */
static uint32_t dv_kb(uint32_t us)
{
    uint32_t x = 47554467u / (us | 1u), x2, x3, x4, k;
    if (x > 46000u)
        x = 46000u;
    x2 = (x * x) >> 16;
    x3 = (x2 * x) >> 16;
    x4 = (x3 * x) >> 16;
    k = 65536u - x + (x2 >> 1) - x3 / 6u + x4 / 24u;
    return k > 65535u ? 65535u : k;
}

static void noise_note_on(track_t *t, voice_t *v)
{
    uint32_t seed = (v->note + 1u) * 0x9E3779B9u ^ (uint32_t)v->fine * 0x85EBCA6Bu;   /* UNISON: each its own */
    (void)t;
    v->s[0] = v->s[1] = 0;
    v->s[2] = (int32_t)(seed ? seed : 1u);
    v->s[3] = 0;                                      /* a new drift target at once */
    v->s[4] = v->s[5] = v->s[6] = v->s[7] = 0;
    v->ph[0] = 0;
    v->ph[1] = 0;
    v->ph[2] = 0;
}

/* stage ix (0..3; 4 = done) of an envelope whose rates and levels are op[FP_R1..], op[FP_L1..] */
static void fm6_env_advance(fm6_env_t *e, const uint8_t *op, uint32_t ix)
{
    int32_t lv, actual, qrate;
    e->ix = (uint8_t)ix;
    if (ix >= 4u)
        return;
    lv = op[FP_L1 + ix];
    actual = fm6_scaleout(lv) >> 1;
    actual = (actual << 6) + e->outlevel - 4256;
    actual = actual < 16 ? 16 : actual;
    e->target = actual << 16;
    e->rising = e->target > e->level;
    qrate = ((op[FP_R1 + ix] * 41) >> 6) + e->rscale;
    qrate = qrate > 63 ? 63 : qrate;
    if (e->target == e->level || (ix == 0u && lv == 0)) {
        int32_t sr = op[FP_R1 + ix] + e->rscale;
        sr = sr > 99 ? 99 : sr;
        e->statc = sr < 77 ? FM6_STATICS[sr] : 20 * (99 - sr);
        if (sr < 77 && ix == 0u && lv == 0)
            e->statc /= 20;                     /* the attack is scaled faster (a stage change, not per sample) */
    } else {
        e->statc = 0;
    }
    e->inc = (4 + (qrate & 3)) << (2 + FM6_LG_N + (qrate >> 2));
}

static void drumx_note_on(track_t *t, voice_t *v)
{
    drumx_lane_t *K = drumx_kit_of(t), *L;
    uint32_t i = (uint32_t)(v - t->v), lane;
    if (!K || i >= NVOICE)
        return;
    lane = drum_lane(v->note);
    L = &K[(uint32_t)v->s[0] & (DV_NLANE - 1u)];
    if (L->owner == i + 1u)                              /* this voice played another lane: it stops there */
        L->owner = 0;
    L = &K[lane];
    L->st = DX_GM[dx_gm_ix(v->note)][1];
    L->owner = (uint8_t)(i + 1u);                        /* (its last voice, if another, ends: drumx_amp) */
    v->s[0] = (int32_t)lane;
    v->env_out = v->vel * 258;                           /* the hit starts at its level (no ramp from 0) */
    v->env = 1 << 24;                                    /* the ADSR held at full from here (eng_drum.c: a key-off
                                                          * before the first block must not end a fresh voice) */
    dx_trigger(&L->x);
    if (lane == DV_HATC)                                 /* a closed hat chokes the open one */
        dx_choke(&K[DV_HATO].x);
}

/* the lane voice v plays, 0 when it plays none (any more) */
static drumx_lane_t *drumx_lane_of(track_t *t, const voice_t *v)
{
    drumx_lane_t *K = drumx_kit_of(t), *L;
    uint32_t i = (uint32_t)(v - t->v);
    if (!K || i >= NVOICE)
        return 0;
    L = &K[(uint32_t)v->s[0] & (DV_NLANE - 1u)];
    return L->owner == i + 1u ? L : 0;
}

